with with_windows as (select id, event_type, page, duration_sec, sum(duration_sec) over (partition by year(event_time) order by duration_sec asc, id asc rows between unbounded preceding and current row) as cumulative_duration_sec, ntile(3) over (partition by session_id order by duration_sec asc, id asc) as duration_sec_bucket from web_events) select case when duration_sec >= 511 then 'LARGE' else 'SMALL' end as duration_sec_tier, count(case when page = '/cart' then 1 end) as cart_count, size(collect_set(event_type)) as num_event_types, count(case when page = '/checkout' then 1 end) as checkout_count from with_windows group by case when duration_sec >= 511 then 'LARGE' else 'SMALL' end having checkout_count > 1 order by duration_sec_tier asc nulls first;
